public class Question_11{static class Node{String code;Node l,r;Node(String s){code=s;}}static Node insert(Node n,String s){if(n==null)return new Node(s);int c=s.compareTo(n.code);if(c<0)n.l=insert(n.l,s);else if(c>0)n.r=insert(n.r,s);return n;}static boolean search(Node n,String s){if(n==null)return false;if(n.code.equals(s))return true;return s.compareTo(n.code)<0?search(n.l,s):search(n.r,s);}static int height(Node n){return n==null?0:1+Math.max(height(n.l),height(n.r));}public static void main(String[]x){String[]a={"CHN","BLR","CBE","HYD","DEL","MUM","PUN"};Node r=null;for(String s:a)r=insert(r,s);System.out.println("Height (nodes): "+height(r));System.out.println("Search HYD: "+search(r,"HYD"));Node z=null;for(String s:new String[]{"A","B","C","D","E"})z=insert(z,s);System.out.println("Height after sorted insertion: "+height(z));}}